if(r==="final check"||B.c.m(r,"final review"))return"Final Reviewer"
if(B.c.m(r,"thumb"))return"Thumbnail Designer"
if(r==="raw photos"||r==="photos clean"||B.c.m(r,"photo select"))return"Raw Photos Selector"
if(r==="selected photos"||r==="photo editing")return"Photo Editor"
if(r==="video editing")return"Video Editor"
