if(B.c.m(r,"uploader")||r==="ready to post")return"Uploader"
if(B.c.m(r,"crosscheck")||B.c.m(r,"cross check"))return"CrossChecker"
if(B.c.m(r,"proof"))return B.c.m(q,s)?"Campaign Proofreader":"Proofreader"
if(B.c.m(r,"edit"))return B.c.m(q,s)?"Campaign Editor":"Editor"
